Tool response:
Tool: update_availability
Description: Update Availability
Parameters:
    {
      "type": "object",
      "properties": {
        "slots": {
          "items": {
            "properties": {
              "day_of_week": {
                "type": "integer",
                "maximum": 6.0,
                "minimum": 0.0,
                "title": "Day Of Week"
              },
              "start_time": {
                "type": "string",
                "title": "Start Time"
              },
              "end_time": {
                "type": "string",
                "title": "End Time"
              },
              "session_duration_minutes": {
                "type": "integer",
                "exclusiveMinimum": 0.0,
                "title": "Session Duration Minutes"
              },
              "is_blocked": {
                "type": "boolean",
                "title": "Is Blocked",
                "default": false
              }
            },
            "type": "object",
            "required": [
              "day_of_week",
              "start_time",
              "end_time",
              "session_duration_minutes"
            ],
            "title": "AvailabilitySlot"
          },
          "type": "array",
          "title": "Slots"
        }
      },
      "required": [
        "slots"
      ]
    }

Tool response:
Tool: delete_availability_slot
Description: Delete Availability Slot
Parameters:
    {
      "type": "object",
      "properties": {
        "slot_id": {
          "type": "integer",
          "title": "Slot Id",
          "description": ""
        }
      },
      "required": [
        "slot_id"
      ]
    }

Tool response:
Tool: bulk_delete_availability_slots
Description: Bulk Delete Availability Slots
Parameters:
    {
      "type": "object",
      "properties": {
        "day_of_week": {
          "type": "integer",
          "maximum": 6.0,
          "minimum": 0.0,
          "title": "Day Of Week"
        }
      },
      "required": [
        "day_of_week"
      ]
    }
